using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SmartFarm.Domain.Entities;

namespace SmartFarm.Infrastructure.Persistence.Configurations;

internal sealed class ControlScheduleConfiguration : IEntityTypeConfiguration<ControlSchedule>
{
    public void Configure(EntityTypeBuilder<ControlSchedule> b)
    {
        b.ToTable("control_schedules", t => { t.HasCheckConstraint("ck_control_schedule_duration", "duration_seconds BETWEEN 1 AND 1800"); t.HasCheckConstraint("ck_control_schedule_rain", "rain_threshold_percent BETWEEN 0 AND 100"); });
        b.HasKey(x => x.Id); DeploymentRequestConfiguration.IdAudit(b); b.Property(x => x.TenantId).HasColumnName("tenant_id"); b.Property(x => x.FarmId).HasColumnName("farm_id"); b.Property(x => x.ZoneId).HasColumnName("zone_id"); b.Property(x => x.ActuatorId).HasColumnName("actuator_id"); b.Property(x => x.Name).HasColumnName("name").HasMaxLength(200); b.Property(x => x.CronExpression).HasColumnName("cron_expression").HasMaxLength(100); b.Property(x => x.DurationSeconds).HasColumnName("duration_seconds"); b.Property(x => x.EnableRainDelay).HasColumnName("enable_rain_delay"); b.Property(x => x.RainThresholdPercent).HasColumnName("rain_threshold_percent").HasPrecision(5, 2); b.Property(x => x.IsActive).HasColumnName("is_active"); b.Property(x => x.NextRunAtUtc).HasColumnName("next_run_at_utc"); b.Property(x => x.ArchivedAtUtc).HasColumnName("archived_at_utc"); b.HasIndex(x => new { x.ZoneId, x.IsActive, x.NextRunAtUtc }); b.HasOne<Tenant>().WithMany().HasForeignKey(x => x.TenantId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Farm>().WithMany().HasForeignKey(x => x.FarmId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Zone).WithMany().HasForeignKey(x => x.ZoneId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Actuator).WithMany().HasForeignKey(x => x.ActuatorId).OnDelete(DeleteBehavior.Restrict);
    }
}

internal sealed class AutoControlRuleConfiguration : IEntityTypeConfiguration<AutoControlRule>
{
    public void Configure(EntityTypeBuilder<AutoControlRule> b)
    {
        b.ToTable("auto_control_rules", t => { t.HasCheckConstraint("ck_auto_rule_duration", "duration_seconds BETWEEN 1 AND 1800"); t.HasCheckConstraint("ck_auto_rule_condition_duration", "condition_duration_minutes BETWEEN 1 AND 1440"); t.HasCheckConstraint("ck_auto_rule_cooldown", "cooldown_minutes BETWEEN 1 AND 10080"); t.HasCheckConstraint("ck_auto_rule_rain", "rain_threshold_percent BETWEEN 0 AND 100"); });
        b.HasKey(x => x.Id); DeploymentRequestConfiguration.IdAudit(b); b.Property(x => x.TenantId).HasColumnName("tenant_id"); b.Property(x => x.FarmId).HasColumnName("farm_id"); b.Property(x => x.ZoneId).HasColumnName("zone_id"); b.Property(x => x.Name).HasColumnName("name").HasMaxLength(200); b.Property(x => x.ParameterCode).HasColumnName("parameter_code").HasConversion<string>().HasMaxLength(30); b.Property(x => x.Operator).HasColumnName("operator").HasConversion<string>().HasMaxLength(30); b.Property(x => x.Threshold).HasColumnName("threshold").HasPrecision(18, 4); b.Property(x => x.ConditionDurationMinutes).HasColumnName("condition_duration_minutes"); b.Property(x => x.ActuatorId).HasColumnName("actuator_id"); b.Property(x => x.Action).HasColumnName("action").HasConversion<string>().HasMaxLength(20); b.Property(x => x.DurationSeconds).HasColumnName("duration_seconds"); b.Property(x => x.Priority).HasColumnName("priority"); b.Property(x => x.CooldownMinutes).HasColumnName("cooldown_minutes"); b.Property(x => x.EnableRainDelay).HasColumnName("enable_rain_delay"); b.Property(x => x.RainThresholdPercent).HasColumnName("rain_threshold_percent").HasPrecision(5, 2); b.Property(x => x.IsActive).HasColumnName("is_active"); b.Property(x => x.LastTriggeredAtUtc).HasColumnName("last_triggered_at_utc"); b.Property(x => x.ConditionTrueSinceUtc).HasColumnName("condition_true_since_utc"); b.Property(x => x.ArchivedAtUtc).HasColumnName("archived_at_utc"); b.HasIndex(x => new { x.ZoneId, x.IsActive }); b.HasOne<Tenant>().WithMany().HasForeignKey(x => x.TenantId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Farm>().WithMany().HasForeignKey(x => x.FarmId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Zone).WithMany().HasForeignKey(x => x.ZoneId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Actuator).WithMany().HasForeignKey(x => x.ActuatorId).OnDelete(DeleteBehavior.Restrict);
    }
}

internal sealed class ActuatorCommandConfiguration : IEntityTypeConfiguration<ActuatorCommand>
{
    public void Configure(EntityTypeBuilder<ActuatorCommand> b)
    {
        b.ToTable("actuator_commands", t => t.HasCheckConstraint("ck_actuator_command_duration", "duration_seconds BETWEEN 1 AND 1800")); b.HasKey(x => x.Id); DeploymentRequestConfiguration.IdAudit(b); b.Property(x => x.TenantId).HasColumnName("tenant_id"); b.Property(x => x.FarmId).HasColumnName("farm_id"); b.Property(x => x.ZoneId).HasColumnName("zone_id"); b.Property(x => x.ActuatorId).HasColumnName("actuator_id"); b.Property(x => x.DeviceId).HasColumnName("device_id"); b.Property(x => x.GatewayId).HasColumnName("gateway_id"); b.Property(x => x.TriggeredByUserId).HasColumnName("triggered_by_user_id"); b.Property(x => x.ScheduleId).HasColumnName("schedule_id"); b.Property(x => x.AutoRuleId).HasColumnName("auto_rule_id"); b.Property(x => x.RecommendationId).HasColumnName("recommendation_id"); b.Property(x => x.IdempotencyKey).HasColumnName("idempotency_key").HasMaxLength(100); b.Property(x => x.TriggerSource).HasColumnName("trigger_source").HasConversion<string>().HasMaxLength(30); b.Property(x => x.Action).HasColumnName("action").HasConversion<string>().HasMaxLength(20); b.Property(x => x.DurationSeconds).HasColumnName("duration_seconds"); b.Property(x => x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(30); b.Property(x => x.Notes).HasColumnName("notes").HasMaxLength(1000); b.Property(x => x.QueuedAtUtc).HasColumnName("queued_at_utc"); b.Property(x => x.SentAtUtc).HasColumnName("sent_at_utc"); b.Property(x => x.AckDeadlineAtUtc).HasColumnName("ack_deadline_at_utc"); b.Property(x => x.AcknowledgedAtUtc).HasColumnName("acknowledged_at_utc"); b.Property(x => x.ExecutionEndsAtUtc).HasColumnName("execution_ends_at_utc"); b.Property(x => x.CancellationRequestedAtUtc).HasColumnName("cancellation_requested_at_utc"); b.Property(x => x.TerminalAtUtc).HasColumnName("terminal_at_utc"); b.Property(x => x.ObservedState).HasColumnName("observed_state").HasMaxLength(50); b.Property(x => x.ErrorCode).HasColumnName("error_code").HasMaxLength(100); b.Property(x => x.ErrorMessage).HasColumnName("error_message").HasMaxLength(1000); b.HasIndex(x => new { x.TenantId, x.IdempotencyKey }).IsUnique(); b.HasIndex(x => new { x.ZoneId, x.Status, x.ExecutionEndsAtUtc }); b.HasOne<Tenant>().WithMany().HasForeignKey(x => x.TenantId).OnDelete(DeleteBehavior.Restrict); b.HasOne<Farm>().WithMany().HasForeignKey(x => x.FarmId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Zone).WithMany().HasForeignKey(x => x.ZoneId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Actuator).WithMany().HasForeignKey(x => x.ActuatorId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Device).WithMany().HasForeignKey(x => x.DeviceId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Gateway).WithMany().HasForeignKey(x => x.GatewayId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.TriggeredByUser).WithMany().HasForeignKey(x => x.TriggeredByUserId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.Schedule).WithMany().HasForeignKey(x => x.ScheduleId).OnDelete(DeleteBehavior.Restrict); b.HasOne(x => x.AutoRule).WithMany().HasForeignKey(x => x.AutoRuleId).OnDelete(DeleteBehavior.Restrict);
    }
}

internal sealed class ActuatorCommandEventConfiguration : IEntityTypeConfiguration<ActuatorCommandEvent>
{
    public void Configure(EntityTypeBuilder<ActuatorCommandEvent> b) { b.ToTable("actuator_command_events"); b.HasKey(x => x.Id); DeploymentRequestConfiguration.IdAudit(b); b.Property(x => x.CommandId).HasColumnName("command_id"); b.Property(x => x.EventKind).HasColumnName("event_kind").HasConversion<string>().HasMaxLength(30); b.Property(x => x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(30); b.Property(x => x.OccurredAtUtc).HasColumnName("occurred_at_utc"); b.Property(x => x.Detail).HasColumnName("detail").HasMaxLength(1000); b.Property(x => x.ObservedState).HasColumnName("observed_state").HasMaxLength(50); b.HasIndex(x => new { x.CommandId, x.OccurredAtUtc }); b.HasOne(x => x.Command).WithMany(x => x.Events).HasForeignKey(x => x.CommandId).OnDelete(DeleteBehavior.Cascade); }
}
